<script setup lang="ts">
import { ref, watch } from 'vue'
import { Link, useForm } from '@inertiajs/vue3'
import { ArrowLeft, Plus, Save, Search, Trash2 } from '@lucide/vue'
interface Department { id: number; name: string }
interface User { id: number; name: string; nik: string | null; departments: Department[] }
interface ItemType { id: number; name: string; unit: string; category: { name: string } | null }
interface HandoverItemForm { item_type_id: string; manual_name: string; manual_unit: string; quantity: number; condition: string; notes: string }
const receiverSearch = ref('')
const receiverResults = ref<User[]>([])
const receiverLoading = ref(false)
const itemSearches = ref<string[]>([''])
const itemResults = ref<ItemType[][]>([[]])
const itemLoading = ref<boolean[]>([false])
const selectedItemType = ref<boolean[]>([false])
let receiverSearchTimeout: ReturnType<typeof setTimeout> | undefined
const itemSearchTimeouts: Record<number, ReturnType<typeof setTimeout>> = {}
const form = useForm({ type: 'PENYERAHAN', receiver_id: '', transaction_date: new Date().toISOString().slice(0, 10), purpose: '', notes: '', items: [{ item_type_id: '', manual_name: '', manual_unit: '', quantity: 1, condition: 'BAIK', notes: '' }] as HandoverItemForm[] })
watch(receiverSearch, (search) => { if (receiverSearchTimeout) clearTimeout(receiverSearchTimeout); receiverResults.value = []; form.receiver_id = ''; if (search.trim().length < 2) return; receiverSearchTimeout = setTimeout(() => searchReceivers(search.trim()), 300) })
async function searchReceivers(search: string): Promise<void> { receiverLoading.value = true; try { const response = await fetch(`${route('handovers.receivers.search')}?search=${encodeURIComponent(search)}`, { headers: { Accept: 'application/json' } }); if (response.ok) receiverResults.value = (await response.json()).users } finally { receiverLoading.value = false } }
function selectReceiver(user: User): void { form.receiver_id = String(user.id); receiverSearch.value = `${user.name}${user.nik ? ` — ${user.nik}` : ''}`; receiverResults.value = [] }
function handleItemSearch(index: number): void { const search = itemSearches.value[index]; selectedItemType.value[index] = false; if (itemSearchTimeouts[index]) clearTimeout(itemSearchTimeouts[index]); itemResults.value[index] = []; form.items[index].item_type_id = ''; if (search.trim().length < 2) return; itemSearchTimeouts[index] = setTimeout(() => searchItemTypes(search.trim(), index), 300) }
async function searchItemTypes(search: string, index: number): Promise<void> { itemLoading.value[index] = true; try { const response = await fetch(`${route('handovers.items.search')}?search=${encodeURIComponent(search)}`, { headers: { Accept: 'application/json' } }); if (response.ok) itemResults.value[index] = (await response.json()).itemTypes } finally { itemLoading.value[index] = false } }
function selectItemType(item: ItemType, index: number): void { selectedItemType.value[index] = true; form.items[index].item_type_id = String(item.id); form.items[index].manual_name = ''; form.items[index].manual_unit = ''; itemSearches.value[index] = `${item.name} — ${item.category?.name ?? 'Tanpa kategori'} (${item.unit})`; itemResults.value[index] = [] }
function addItem(): void { form.items.push({ item_type_id: '', manual_name: '', manual_unit: '', quantity: 1, condition: 'BAIK', notes: '' }); itemSearches.value.push(''); itemResults.value.push([]); itemLoading.value.push(false); selectedItemType.value.push(false) }
function removeItem(index: number): void { if (form.items.length > 1) { form.items.splice(index, 1); itemSearches.value.splice(index, 1); itemResults.value.splice(index, 1); itemLoading.value.splice(index, 1); selectedItemType.value.splice(index, 1) } }
function submit(): void { form.post(route('handovers.store')) }
</script>
<template>
  <div class="min-h-screen pb-8"><header class="sticky top-0 z-10 border-b bg-white/95 px-4 py-4 backdrop-blur"><div class="mx-auto flex max-w-3xl items-center gap-3"><Link :href="route('handovers.index')" class="rounded-xl p-2 text-muted-foreground"><ArrowLeft class="size-5" /></Link><div><p class="text-xs uppercase tracking-wider text-primary">Transaksi Baru</p><h1 class="text-xl font-bold">Buat Serah Terima</h1></div></div></header><main class="mx-auto max-w-3xl px-4 py-6"><form class="space-y-5" @submit.prevent="submit"><section class="space-y-4 rounded-3xl border bg-card p-5"><div><label class="mb-2 block text-sm font-medium">Jenis transaksi</label><select v-model="form.type" class="w-full rounded-xl border bg-background px-4 py-3"><option>PENYERAHAN</option><option>PENGEMBALIAN</option><option>PEMINJAMAN</option><option>PENGGANTIAN</option><option>MUTASI</option></select><p v-if="form.errors.type" class="mt-1 text-sm text-red-600">{{ form.errors.type }}</p></div><div class="relative"><label for="receiver-search" class="mb-2 block text-sm font-medium">Pihak menerima</label><div class="relative"><Search class="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input id="receiver-search" v-model="receiverSearch" type="search" class="w-full rounded-xl border bg-background py-3 pl-10 pr-4" placeholder="Cari nama, NIK, atau departemen" autocomplete="off"><span v-if="receiverLoading" class="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">Mencari...</span></div><div v-if="receiverSearch.trim().length >= 2 && !form.receiver_id" class="absolute inset-x-0 top-full z-20 mt-1 overflow-hidden rounded-xl border bg-background shadow-lg"><p v-if="!receiverLoading && !receiverResults.length" class="p-3 text-sm text-muted-foreground">User tidak ditemukan.</p><button v-for="user in receiverResults" :key="user.id" type="button" class="block w-full border-b px-4 py-3 text-left last:border-0 hover:bg-muted" @click="selectReceiver(user)"><span class="block text-sm font-medium">{{ user.name }}</span><span class="block text-xs text-muted-foreground">{{ user.nik || 'NIK tidak tersedia' }} · {{ user.departments.map((department) => department.name).join(', ') || 'Tanpa departemen' }}</span></button></div><p v-if="form.receiver_id" class="mt-2 text-xs text-green-700">Penerima dipilih.</p><p v-if="form.errors.receiver_id" class="mt-1 text-sm text-red-600">{{ form.errors.receiver_id }}</p></div><div><label class="mb-2 block text-sm font-medium">Tanggal transaksi</label><input v-model="form.transaction_date" type="date" class="w-full rounded-xl border bg-background px-4 py-3"></div><div><label class="mb-2 block text-sm font-medium">Keperluan <span class="font-normal text-muted-foreground">(opsional)</span></label><textarea v-model="form.purpose" rows="2" class="w-full rounded-xl border bg-background px-4 py-3"></textarea></div></section><section class="space-y-4 rounded-3xl border bg-card p-5"><div class="flex items-center justify-between"><h2 class="font-semibold">Barang</h2><button type="button" class="flex items-center gap-1 rounded-xl border px-3 py-2 text-sm" @click="addItem"><Plus class="size-4" />Tambah</button></div><div v-for="(item, index) in form.items" :key="index" class="space-y-3 rounded-2xl border p-4"><div class="flex items-center justify-between"><p class="text-sm font-medium">Barang {{ index + 1 }}</p><button v-if="form.items.length > 1" type="button" class="rounded-lg p-2 text-red-600" @click="removeItem(index)"><Trash2 class="size-4" /></button></div><div class="relative"><Search class="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input v-model="itemSearches[index]" type="search" @input="handleItemSearch(index)" class="w-full rounded-xl border bg-background py-3 pl-10 pr-4" placeholder="Cari nama atau kategori barang" autocomplete="off"><span v-if="itemLoading[index]" class="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">Mencari...</span><div v-if="itemSearches[index].trim().length >= 2 && !item.item_type_id && !selectedItemType[index]" class="absolute inset-x-0 top-full z-20 mt-1 overflow-hidden rounded-xl border bg-background shadow-lg"><p v-if="!itemLoading[index] && !itemResults[index].length" class="p-3 text-sm text-muted-foreground">Barang tidak ditemukan.</p><button v-for="itemType in itemResults[index]" :key="itemType.id" type="button" class="block w-full border-b px-4 py-3 text-left last:border-0 hover:bg-muted" @click="selectItemType(itemType, index)"><span class="block text-sm font-medium">{{ itemType.name }}</span><span class="block text-xs text-muted-foreground">{{ itemType.category?.name ?? 'Tanpa kategori' }} · {{ itemType.unit }}</span></button></div></div><div class="grid grid-cols-2 gap-3"><input v-model="item.manual_name" type="text" class="w-full rounded-xl border bg-background px-4 py-3" placeholder="Atau nama barang manual"><input v-model="item.manual_unit" type="text" class="w-full rounded-xl border bg-background px-4 py-3" placeholder="Satuan"><input v-model.number="item.quantity" type="number" min="1" class="w-full rounded-xl border bg-background px-4 py-3" placeholder="Jumlah"><select v-model="item.condition" class="w-full rounded-xl border bg-background px-4 py-3"><option>BAIK</option><option>RUSAK RINGAN</option><option>RUSAK BERAT</option></select></div><input v-model="item.notes" class="w-full rounded-xl border bg-background px-4 py-3" placeholder="Catatan barang (opsional)"></div><p v-if="form.errors.items" class="text-sm text-red-600">{{ form.errors.items }}</p><p v-if="Object.entries(form.errors).some(([key]) => key.startsWith('items.'))" class="text-sm text-red-600">Setiap item harus memilih barang master atau mengisi nama barang manual.</p></section><section class="rounded-3xl border bg-card p-5"><label class="mb-2 block text-sm font-medium">Catatan umum <span class="font-normal text-muted-foreground">(opsional)</span></label><textarea v-model="form.notes" rows="3" class="w-full rounded-xl border bg-background px-4 py-3"></textarea></section><button type="submit" :disabled="form.processing" class="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 font-semibold text-primary-foreground"><Save class="size-4" />{{ form.processing ? 'Menyimpan...' : 'Simpan transaksi' }}</button></form></main></div>
</template>
